// ========================================
// AI LEAD INTAKE
// Normalize & Validate Lead
// ========================================

// Разрешённые поля заявки
const FIELDS = [
  "request_id",
  "name",
  "contact",
  "service",
  "budget",
  "message",
  "timeline"
];

// Разрешённые услуги
const SERVICES = new Set([
  "AI-автоматизация продаж",
  "Автоматизация документооборота",
  "AI-бот и поддержка клиентов",
  "Интеграция CRM и бизнес-систем",
  "Другая AI-автоматизация"
]);

// Разрешённые сроки
const TIMELINES = new Set([
  "Срочно — до 7 дней",
  "1–2 недели",
  "До 1 месяца",
  "1–3 месяца",
  "Сроки гибкие"
]);

// ========================================
// UNICODE HELPERS
// ========================================

// Пробельные символы, распознаваемые
// Python str.isspace() / str.split().
const PY_WS =
  /[\u0009-\u000D\u001C-\u0020\u0085\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000]/u;

const PY_WS_RUN =
  /[\u0009-\u000D\u001C-\u0020\u0085\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000]+/u;

const PY_WS_EDGES =
  /^[\u0009-\u000D\u001C-\u0020\u0085\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000]+|[\u0009-\u000D\u001C-\u0020\u0085\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000]+$/gu;

// Python считает длину строки в Unicode code points,
// а JavaScript .length — в UTF-16 code units.
function pyLength(value) {
  return Array.from(value).length;
}

function pyTrim(value) {
  return value.replace(PY_WS_EDGES, "");
}

function isCombiningMark(char) {
  return /^\p{M}$/u.test(char);
}

// ========================================
// NAME
// ========================================

function normalizeName(value) {
  if (typeof value !== "string") {
    return null;
  }

  return value
    .split(PY_WS_RUN)
    .filter(Boolean)
    .join(" ");
}

function validName(value) {
  if (value === null) {
    return false;
  }

  const chars = Array.from(value);

  if (chars.length < 2 || chars.length > 60) {
    return false;
  }

  let letterCount = 0;

  for (const char of chars) {

    if (/^\p{L}$/u.test(char)) {
      letterCount++;
      continue;
    }

    if (isCombiningMark(char)) {
      continue;
    }

    if ([" ", "-", "'", "’"].includes(char)) {
      continue;
    }

    return false;
  }

  return letterCount >= 2;
}

// ========================================
// TELEGRAM
// ========================================

function validTelegramUsername(value) {
  if (!value.startsWith("@")) {
    return false;
  }

  const username = value.slice(1);

  if (username.length < 5 || username.length > 32) {
    return false;
  }

  return /^[A-Za-z][A-Za-z0-9_]*$/.test(username);
}

// ========================================
// EMAIL
// ========================================

const ALLOWED_EMAIL_LOCAL = new Set(
  Array.from(
    "abcdefghijklmnopqrstuvwxyz" +
    "ABCDEFGHIJKLMNOPQRSTUVWXYZ" +
    "0123456789" +
    "!#$%&'*+/=?^_`{|}~-"
  )
);

function validEmail(value) {

  if (pyLength(value) > 254) {
    return false;
  }

  if (PY_WS.test(value)) {
    return false;
  }

  const atParts = value.split("@");

  if (atParts.length !== 2) {
    return false;
  }

  const [local, domain] = atParts;

  if (
    pyLength(local) < 1 ||
    pyLength(local) > 64
  ) {
    return false;
  }

  const localParts = local.split(".");

  for (const part of localParts) {

    if (!part) {
      return false;
    }

    for (const char of part) {
      if (!ALLOWED_EMAIL_LOCAL.has(char)) {
        return false;
      }
    }
  }

  const labels = domain.split(".");

  if (labels.length < 2) {
    return false;
  }

  for (const label of labels) {

    if (label.length < 1 || label.length > 63) {
      return false;
    }

    if (!/^[A-Za-z0-9]/.test(label)) {
      return false;
    }

    if (!/[A-Za-z0-9]$/.test(label)) {
      return false;
    }

    if (!/^[A-Za-z0-9-]+$/.test(label)) {
      return false;
    }
  }

  const tld = labels[labels.length - 1];

  if (tld.length < 2 || tld.length > 63) {
    return false;
  }

  return /^[A-Za-z]+$/.test(tld);
}

// ========================================
// CONTACT
// ========================================

function normalizeContact(contact) {

  if (typeof contact !== "string") {
    return null;
  }

  const colonIndex = contact.indexOf(":");

  if (colonIndex === -1) {
    return null;
  }

  const contactType = contact.slice(
    0,
    colonIndex
  );

  const value = pyTrim(
    contact.slice(colonIndex + 1)
  );

  // Telegram
  if (contactType === "Telegram") {

    if (!validTelegramUsername(value)) {
      return null;
    }

    return (
      "Telegram: @" +
      value.slice(1).toLowerCase()
    );
  }

  // Российский телефон
  if (contactType === "Телефон") {

    if (pyLength(value) !== 12) {
      return null;
    }

    if (!value.startsWith("+7")) {
      return null;
    }

    if (!/^[0-9]{10}$/.test(value.slice(2))) {
      return null;
    }

    return "Телефон: " + value;
  }

  // Email
  if (contactType === "Email") {

    if (!validEmail(value)) {
      return null;
    }

    return "Email: " + value.toLowerCase();
  }

  return null;
}

// ========================================
// UUID VERSION 4
// ========================================

function validUUID4(value) {

  if (typeof value !== "string") {
    return false;
  }

  return (
    /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/
      .test(value)
  );
}

// ========================================
// NORMALIZE & VALIDATE EVERY ITEM
// ========================================

const startedAt = Date.now();
return $input.all().map((item, index) => {

  // Получаем HTTP body
  const body = item.json?.body;

  const source =
    body &&
    typeof body === "object" &&
    !Array.isArray(body)
      ? body
      : {};

  // Оставляем только разрешённые поля
  const input = {};

  for (const field of FIELDS) {
    if (
      Object.prototype.hasOwnProperty.call(
        source,
        field
      )
    ) {
      input[field] = source[field];
    }
  }

  const fieldErrors = {};

  // NAME
  const rawName = input.name ?? null;
  const name = normalizeName(rawName);

  if (typeof rawName !== "string") {

    fieldErrors.name = "Укажите имя.";

  } else if (!validName(name)) {

    fieldErrors.name =
      "Укажите имя: от 2 до 60 символов, " +
      "буквы, пробелы, дефис или апостроф.";
  }

  // SERVICE
  const service = input.service ?? null;

  if (
    typeof service !== "string" ||
    !SERVICES.has(service)
  ) {

    fieldErrors.service =
      "Выберите услугу из списка.";
  }

  // CONTACT
  const contact = normalizeContact(
    input.contact ?? null
  );

  if (contact === null) {

    fieldErrors.contact =
      "Укажите корректный Telegram, " +
      "email или российский телефон.";
  }

  // BUDGET
  const budget = input.budget ?? null;

  if (budget !== null) {

    if (
      typeof budget !== "number" ||
      !Number.isInteger(budget) ||
      budget < 1 ||
      budget > 1000000000
    ) {

      fieldErrors.budget =
        "Укажите бюджет в рублях: " +
        "целое число от 1 до 1 000 000 000 " +
        "или оставьте поле пустым.";
    }
  }

  // TIMELINE
  let timeline = input.timeline ?? null;

  if (timeline === "") {
    timeline = null;
  }

  if (timeline !== null) {

    if (
      typeof timeline !== "string" ||
      !TIMELINES.has(timeline)
    ) {

      fieldErrors.timeline =
        "Выберите срок из списка.";
    }
  }

  // MESSAGE
  let message = input.message ?? null;

  if (typeof message === "string") {

    message = pyTrim(message);

    if (
      message.includes("\u0000") ||
      pyLength(message) < 20 ||
      pyLength(message) > 2000
    ) {

      fieldErrors.message =
        "Опишите задачу: от 20 до 2000 символов.";
    }

  } else {

    fieldErrors.message = "Опишите задачу.";
  }

  // REQUEST ID
  const requestId = input.request_id ?? null;

  if (!validUUID4(requestId)) {

    fieldErrors.request_id =
      "Некорректный идентификатор заявки. " +
      "Обновите страницу.";
  }

  // FINAL OUTPUT
  return {
    json: {

      intake_started_at: startedAt,
      validation_ms: Date.now() - startedAt,
      payload: { request_id: requestId, name, contact, service, budget, message, timeline },
      request_id: requestId,
      name,
      contact,
      service,
      budget,
      message,
      timeline,

      is_valid:
        Object.keys(fieldErrors).length === 0,

      validation_errors:
        Object.values(fieldErrors),

      field_errors:
        fieldErrors
    },

    pairedItem: {
      item: index
    }
  };
});
